diff --git a/sputnikdao2/src/proposals.rs b/sputnikdao2/src/proposals.rs
index 3c41adf..87d4d91 100644
--- a/sputnikdao2/src/proposals.rs
+++ b/sputnikdao2/src/proposals.rs
@@ -336,7 +336,110 @@ impl Contract {
         }
     }

-    fn internal_return_bonds(&mut self, policy: &Policy, proposal: &Proposal) -> Promise {
+    const REFUND_OPEN: u8 = 0;
+    const REFUND_IN_FLIGHT: u8 = 1;
+    const REFUND_SETTLED: u8 = 2;
+    const REFUND_FAILED: u8 = 3;
+    const GAS_FOR_REFUND_CALLBACK: Gas = Gas::from_tgas(20);
+
+    fn proposal_bond_key(proposal_id: u64) -> Vec<u8> {
+        let mut key = b"proposal_bond:".to_vec();
+        key.extend_from_slice(&proposal_id.to_le_bytes());
+        key
+    }
+
+    fn refund_state_key(proposal_id: u64) -> Vec<u8> {
+        let mut key = b"proposal_refund:".to_vec();
+        key.extend_from_slice(&proposal_id.to_le_bytes());
+        key
+    }
+
+    fn read_refund_state(proposal_id: u64) -> Option<(u8, u64, u128)> {
+        let value = env::storage_read(&Self::refund_state_key(proposal_id))?;
+        if value.len() != 25 {
+            env::panic_str("ERR_INVALID_REFUND_STATE");
+        }
+        let mut attempt = [0u8; 8];
+        attempt.copy_from_slice(&value[1..9]);
+        let mut bond = [0u8; 16];
+        bond.copy_from_slice(&value[9..]);
+        Some((
+            value[0],
+            u64::from_le_bytes(attempt),
+            u128::from_le_bytes(bond),
+        ))
+    }
+
+    fn write_refund_state(proposal_id: u64, status: u8, attempt: u64, bond: u128) {
+        let mut value = Vec::with_capacity(25);
+        value.push(status);
+        value.extend_from_slice(&attempt.to_le_bytes());
+        value.extend_from_slice(&bond.to_le_bytes());
+        env::storage_write(&Self::refund_state_key(proposal_id), &value);
+    }
+
+    fn legacy_bond_provenance_key(proposal_id: u64) -> Vec<u8> {
+        let mut key = b"legacy_proposal_bond_provenance:".to_vec();
+        key.extend_from_slice(&proposal_id.to_le_bytes());
+        key
+    }
+
+    fn proposal_bond_amount(proposal_id: u64) -> Option<u128> {
+        let value = env::storage_read(&Self::proposal_bond_key(proposal_id))?;
+        if value.len() != 16 {
+            env::panic_str("ERR_INVALID_PROPOSAL_BOND");
+        }
+        Some(u128::from_le_bytes(value.try_into().unwrap()))
+    }
+
+    fn internal_return_proposal_bond(
+        &mut self,
+        proposal_id: u64,
+        proposal: &Proposal,
+    ) -> PromiseOrValue<()> {
+        let Some(amount) = Self::proposal_bond_amount(proposal_id) else {
+            log!(
+                "Refusing refund for proposal {} without a trusted legacy principal",
+                proposal_id
+            );
+            return PromiseOrValue::Value(());
+        };
+        if amount == 0 {
+            return PromiseOrValue::Value(());
+        }
+        let (status, attempt, recorded_bond) =
+            Self::read_refund_state(proposal_id).unwrap_or((Self::REFUND_OPEN, 0, amount));
+        let bond = if recorded_bond == 0 {
+            amount
+        } else {
+            recorded_bond
+        };
+        if bond != amount {
+            env::panic_str("ERR_PROPOSAL_BOND_MISMATCH");
+        }
+        match status {
+            Self::REFUND_SETTLED | Self::REFUND_IN_FLIGHT => return PromiseOrValue::Value(()),
+            Self::REFUND_OPEN | Self::REFUND_FAILED => {}
+            _ => env::panic_str("ERR_INVALID_REFUND_STATE"),
+        }
+        let next_attempt = attempt.checked_add(1).expect("ERR_REFUND_ATTEMPT_OVERFLOW");
+        Self::write_refund_state(proposal_id, Self::REFUND_IN_FLIGHT, next_attempt, bond);
+        Promise::new(proposal.proposer.clone())
+            .transfer(NearToken::from_yoctonear(bond))
+            .then(
+                Self::ext(env::current_account_id())
+                    .with_static_gas(Self::GAS_FOR_REFUND_CALLBACK)
+                    .on_refund_callback(proposal_id, next_attempt),
+            )
+            .into()
+    }
+
+    fn internal_return_bonds(
+        &mut self,
+        proposal_id: u64,
+        policy: &Policy,
+        proposal: &Proposal,
+    ) -> PromiseOrValue<()> {
         if let ProposalKind::BountyDone { .. } = &proposal.kind {
             self.locked_amount = self.locked_amount.saturating_sub(policy.bounty_bond);
             Promise::new(proposal.proposer.clone())
@@ -344,8 +447,7 @@ impl Contract {
                 .detach();
         }

-        self.locked_amount = self.locked_amount.saturating_sub(policy.proposal_bond);
-        Promise::new(proposal.proposer.clone()).transfer(policy.proposal_bond)
+        self.internal_return_proposal_bond(proposal_id, proposal)
     }

     /// Executes given proposal and updates the contract's state.
@@ -466,12 +568,13 @@ impl Contract {
                         .on_proposal_callback(proposal_id),
                 )
                 .into(),
-            PromiseOrValue::Value(()) => self.internal_return_bonds(policy, proposal).into(),
+            PromiseOrValue::Value(()) => self.internal_return_bonds(proposal_id, policy, proposal),
         }
     }

     pub(crate) fn internal_callback_proposal_success(
         &mut self,
+        proposal_id: u64,
         proposal: &mut Proposal,
     ) -> PromiseOrValue<()> {
         let policy = self.policy.get().unwrap().to_policy();
@@ -486,27 +589,30 @@ impl Contract {
             }
         }
         proposal.status = ProposalStatus::Approved;
-        self.internal_return_bonds(&policy, proposal).into()
+        self.internal_return_bonds(proposal_id, &policy, proposal)
     }

     pub(crate) fn internal_callback_proposal_fail(
         &mut self,
+        proposal_id: u64,
         proposal: &mut Proposal,
     ) -> PromiseOrValue<()> {
         proposal.status = ProposalStatus::Failed;
-        PromiseOrValue::Value(())
+        self.internal_return_proposal_bond(proposal_id, proposal)
     }

     /// Process rejecting proposal.
     fn internal_reject_proposal(
         &mut self,
+        proposal_id: u64,
         policy: &Policy,
         proposal: &Proposal,
         return_bonds: bool,
     ) -> PromiseOrValue<()> {
         if return_bonds {
-            // Return bond to the proposer.
-            self.internal_return_bonds(policy, proposal).detach();
+            // Return bond to the proposer through the receipt-settled path.
+            self.internal_return_bonds(proposal_id, policy, proposal)
+                .detach();
         }

         let proposal_data = proposal;
@@ -530,6 +636,50 @@ impl Contract {

 #[near]
 impl Contract {
+    /// Trusted migration input for a proposal created before per-proposal
+    /// principal was recorded. This is a bounded, one-time seed: it never
+    /// changes locked debt or governance, and it refuses a second seed.
+    #[private]
+    pub fn seed_legacy_proposal_bond(
+        &mut self,
+        proposal_id: u64,
+        proposer: AccountId,
+        amount: U128,
+        funding_tx_hash: String,
+    ) {
+        let amount = amount.0;
+        assert!(amount > 0, "ERR_INVALID_LEGACY_BOND");
+        assert!(
+            (43..=44).contains(&funding_tx_hash.len())
+                && funding_tx_hash
+                    .bytes()
+                    .all(|byte| byte.is_ascii_alphanumeric() && !b"0OIl".contains(&byte)),
+            "ERR_INVALID_FUNDING_TX_HASH"
+        );
+        let proposal: Proposal = self
+            .proposals
+            .get(&proposal_id)
+            .expect("ERR_NO_PROPOSAL")
+            .into();
+        assert_eq!(
+            proposal.proposer, proposer,
+            "ERR_LEGACY_BOND_PROPOSAL_MISMATCH"
+        );
+        assert!(
+            env::storage_read(&Self::proposal_bond_key(proposal_id)).is_none(),
+            "ERR_LEGACY_BOND_ALREADY_RECORDED"
+        );
+        assert!(
+            env::storage_read(&Self::refund_state_key(proposal_id)).is_none(),
+            "ERR_LEGACY_REFUND_ALREADY_STARTED"
+        );
+        env::storage_write(&Self::proposal_bond_key(proposal_id), &amount.to_le_bytes());
+        let mut provenance = Vec::with_capacity(80);
+        provenance.extend_from_slice(funding_tx_hash.as_bytes());
+        provenance.extend_from_slice(&amount.to_le_bytes());
+        env::storage_write(&Self::legacy_bond_provenance_key(proposal_id), &provenance);
+    }
+
     /// Add proposal to this DAO.
     #[payable]
     pub fn add_proposal(&mut self, proposal: ProposalInput) -> u64 {
@@ -583,6 +733,16 @@ impl Contract {

         self.proposals
             .insert(&id, &VersionedProposal::Latest(proposal));
+        env::storage_write(
+            &Self::proposal_bond_key(id),
+            &env::attached_deposit().as_yoctonear().to_le_bytes(),
+        );
+        env::storage_write(&Self::refund_state_key(id), &{
+            let mut value = vec![Self::REFUND_OPEN];
+            value.extend_from_slice(&0u64.to_le_bytes());
+            value.extend_from_slice(&env::attached_deposit().as_yoctonear().to_le_bytes());
+            value
+        });
         self.last_proposal_id += 1;
         self.locked_amount = self.locked_amount.saturating_add(env::attached_deposit());
         id
@@ -642,12 +802,12 @@ impl Contract {
                         .detach();
                     true
                 } else if proposal.status == ProposalStatus::Removed {
-                    self.internal_reject_proposal(&policy, &proposal, false)
+                    self.internal_reject_proposal(id, &policy, &proposal, false)
                         .detach();
                     self.proposals.remove(&id);
                     false
                 } else if proposal.status == ProposalStatus::Rejected {
-                    self.internal_reject_proposal(&policy, &proposal, true)
+                    self.internal_reject_proposal(id, &policy, &proposal, true)
                         .detach();
                     true
                 } else {
@@ -674,7 +834,7 @@ impl Contract {
                             .detach();
                     }
                     ProposalStatus::Expired => {
-                        self.internal_reject_proposal(&policy, &proposal, true)
+                        self.internal_reject_proposal(id, &policy, &proposal, true)
                             .detach();
                     }
                     _ => {
@@ -712,12 +872,42 @@ impl Contract {
             "ERR_UNEXPECTED_CALLBACK_PROMISES"
         );
         let result = if utils::is_promise_success() {
-            self.internal_callback_proposal_success(&mut proposal)
+            self.internal_callback_proposal_success(proposal_id, &mut proposal)
         } else {
-            self.internal_callback_proposal_fail(&mut proposal)
+            self.internal_callback_proposal_fail(proposal_id, &mut proposal)
         };
         self.proposals
             .insert(&proposal_id, &VersionedProposal::Latest(proposal));
         result
     }
+
+    /// Settles a proposal-bond refund only after the transfer receipt succeeds.
+    /// A failed transfer restores the debt; a stale or duplicate callback is ignored.
+    #[private]
+    pub fn on_refund_callback(&mut self, proposal_id: u64, attempt: u64) -> PromiseOrValue<()> {
+        assert_eq!(
+            env::promise_results_count(),
+            1,
+            "ERR_UNEXPECTED_REFUND_CALLBACK_PROMISES"
+        );
+        let (status, current_attempt, bond) = Self::read_refund_state(proposal_id)
+            .unwrap_or_else(|| env::panic_str("ERR_INVALID_REFUND_STATE"));
+        if status != Self::REFUND_IN_FLIGHT || current_attempt != attempt {
+            log!(
+                "Ignoring stale refund callback for proposal {} attempt {}",
+                proposal_id,
+                attempt
+            );
+            return PromiseOrValue::Value(());
+        }
+        if utils::is_promise_success() {
+            self.locked_amount = self
+                .locked_amount
+                .saturating_sub(NearToken::from_yoctonear(bond));
+            Self::write_refund_state(proposal_id, Self::REFUND_SETTLED, attempt, bond);
+        } else {
+            Self::write_refund_state(proposal_id, Self::REFUND_FAILED, attempt, bond);
+        }
+        PromiseOrValue::Value(())
+    }
 }

